/* Local deterministic operating application. All fictional business data stays in this browser. */
(() => {
'use strict';
const D=globalThis.SD_DATA,M=globalThis.SDModel,E=globalThis.SimEngine,R=globalThis.DR_RECORDED;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), clone=v=>JSON.parse(JSON.stringify(v));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v||0), num=v=>Number(v).toFixed(3), stamp=()=>new Date().toISOString();
const views=[['today','Today'],['accounts','Accounts'],['integration','Integration'],['people','People'],['product','Product & Partners'],['room','Danger Room'],['school','Danger School'],['review','Operating Review'],['evidence','Evidence & Handoff']];
const seed=()=>({schema:'simulation-director-workspace@1',version:D.version,asOf:D.asOf,opportunities:clone(D.opportunities),people:clone(D.people),partners:clone(D.partners),integration:{reconciled:false},quality:{requiredScope:'timing',accepted:null,suites:[],runs:[],curriculum:[]},actions:[],events:[]});
let state=seed(),view='today',snapshot=0,playing=null,busy=false,storageError='',captureAnalysis=null;
function validate(v){if(!v||v.schema!=='simulation-director-workspace@1')throw Error('This is not a Simulation Director workspace.');if(!/^\d{4}-\d{2}-\d{2}$/.test(v.asOf))throw Error('A valid as-of date is required.');for(const k of ['opportunities','people','partners','actions','events'])if(!Array.isArray(v[k])||v[k].length>10000)throw Error('Invalid '+k+' collection.');if(!v.quality||!['timing','expanded'].includes(v.quality.requiredScope)||!['runs','suites','curriculum'].every(k=>Array.isArray(v.quality[k])))throw Error('Invalid quality records.');if(!v.integration||typeof v.integration!=='object')throw Error('Missing integration record.');for(const o of v.opportunities)if(!o||typeof o.id!=='string'||typeof o.name!=='string'||!Number.isFinite(o.amount)||o.amount<0)throw Error('Opportunity IDs, names and nonnegative amounts are required.');if(new Set(v.opportunities.map(o=>o.id)).size!==v.opportunities.length)throw Error('Duplicate opportunity IDs are not permitted.');return v;}
try{const saved=localStorage.getItem('ddv-sim-v1');if(saved)state=validate(JSON.parse(saved));}catch(e){storageError='Saved workspace could not be loaded: '+e.message;}
// Admission stays blocked until saved evidence has been independently checked.
const bootCandidate=clone(state);
if(state.quality.accepted){state.quality.accepted=null;busy=true;}
function save(){try{localStorage.setItem('ddv-sim-v1',JSON.stringify(state));if(!storageError.startsWith('Saved'))storageError='';}catch(e){storageError='Browser storage unavailable or full. Export your workspace now; this session remains in memory.';}status();}
function event(action,detail={}){state.events.push({id:'EV-'+Date.now()+'-'+state.events.length,at:stamp(),action,detail});save();}
function status(){$('#status').textContent=storageError||`${state.events.length} recorded actions · fictional workspace · ${state.asOf} · local browser`;}function toast(t){$('#toast').textContent=t;setTimeout(()=>{$('#toast').textContent='';},4200);}
function download(name,content,type='application/json'){const blob=new Blob([typeof content==='string'?content:JSON.stringify(content,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const btn=(text,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${esc(action)}" data-id="${esc(id)}">${esc(text)}</button>`;
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const card=(title,body,extra='')=>`<section class="card"><div class="card-head"><h2>${esc(title)}</h2>${extra}</div>${body}</section>`;
const head=(title,desc,actions='')=>`<header class="view-head"><div><span class="eyebrow">Simulation Director / ${esc(view)}</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></header>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(s=>`<th scope="col">${esc(s)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">No records yet.</td></tr>`}</tbody></table></div>`;
const row=items=>`<tr>${items.map(s=>`<td>${s}</td>`).join('')}</tr>`;
const owner=id=>state.people.find(p=>p.id===id)?.name||id||'Unassigned';
function metrics(){const m=M.metrics(state),c=M.coverage(state);return `<div class="metric-grid">${[['Open pipeline · USD',money(m.openPipeline),'Excludes duplicates after reconciliation'],['Commit',money(m.commit),'Commercial review + every gate'],['Closed-won bookings',money(m.closedWonBookings),'Recognized revenue is not supplied'],['Coverage',Math.round(c.coveragePct)+'%',c.backupGaps.length+' backup gaps']].map(([k,v,n])=>`<div class="metric"><span>${esc(k)}</span><strong>${esc(v)}</strong><small>${esc(n)}</small></div>`).join('')}</div>`;}
function actionsList(){return state.actions.length?`<div class="record-list">${state.actions.map(a=>`<article class="record"><div><h3>${esc(a.title)}</h3><p>${esc(a.oppId||'Department')} · ${esc(owner(a.owner))} · due ${esc(a.due||'unassigned')}</p>${tag(a.status,a.status==='done'?'good':'warn')}</div>${btn(a.status==='done'?'Reopen':'Complete','action-toggle',a.id,'small')}</article>`).join('')}</div>`:'<div class="empty">No actions yet. Generate a gap plan or run the working day.</div>';}
function today(){return `<section class="hero"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">A working department, in one browser</span><h1>We were asked for a CV.<br>We brought the department.</h1><p>Integration, people, markets, strategic pursuits, product packaging, partners, revenue operations and engineering evidence—joined into one inspectable working practice. Jonathan brings the judgment; this application does the bookkeeping and makes the tradeoffs visible.</p><div class="actions">${btn('Run the working day →','working-day','','primary')}${btn('Inspect the original Danger Room','navigate','room')}</div></div><div class="hero-figure"><span class="eyebrow">Commercial intent → dependable delivery</span><div class="flow">${['Qualify the outcome','Assign people & partners','Replay the failure','Learn & evaluate','Release a scoped claim','Handoff & review'].map((t,i)=>`<div class="flow-step"><span class="eyebrow">0${i+1}</span><strong>${t}</strong></div>`).join('')}</div><p class="fine-print">A local application authored by agents. Deterministic rules execute here; no live LLM, CRM, private Shield AI data or external API.</p></div></div></section>${metrics()}<div class="callout warn">${esc(D.disclosure)} The original native Fly-0 receipt, new browser experiment and commercial examples are three distinct evidence classes.</div><div class="grid two">${card('Eight accountable functions',`<div class="record-list">${D.functions.map(f=>`<div class="record"><div><h3>${esc(f.agent)}</h3><p>${esc(f.title)} · ${esc(f.output)}</p></div>${btn('Open','navigate',f.view,'small')}</div>`).join('')}</div>`)}${card('The next useful move',actionsList(),btn('Generate gap actions','gaps','','small'))}</div>`;}
function accounts(){const ranks=M.rankAccounts(state);return head('Accounts & strategic pursuits','Ranked by disclosed fit and recorded gates. Scores are illustrative policy, not private market intelligence.',btn('Intake opportunity JSON','intake')+btn('New opportunity','new-opp','','primary'))+table(['Priority / account','Stage / value','Coverage','Readiness','Next move'],ranks.map(r=>{const o=r.opportunity,f=M.forecastOne(o,state);return row([`<strong>${r.score}/100 · ${esc(o.name)}</strong><small>${esc(o.id)} · ${esc(o.region)} · ${esc(o.segment)}</small>`,`${esc(M.normalizeStage(o.stage))}<br>${money(o.amount)}`,`${esc(owner(o.owner))}<small>Backup: ${esc(owner(o.backup))}</small>`,tag(f.category,f.category==='commit'?'good':'warn')+`<small>${esc(f.blockers.join('; '))}</small>`,btn('Edit / qualify','edit-opp',o.id,'small')+' '+btn('Pursuit brief','brief',o.id,'small')]);}))+card('Account planning & demand hypothesis','<p>Prioritize primes, integrators, government research and enterprise development teams with a named decision owner and repeatable evaluation need. Test a narrow offer: one customer problem, one interface discovery session and one measurable acceptance contract.</p><p>Measure discovery-to-qualified conversion against a dated cohort; no conversion uplift is claimed by this workspace.</p>'+btn('Generate market brief','market-brief')+btn('Build mutual action plans','gaps'));}
function integration(){const i=state.integration;return head('One operating model. Sources intact.','Unify legacy stages and explicit duplicate keys while retaining every original source record.',btn('Reconcile source records','reconcile','','primary'))+`<div class="callout ${i.reconciled?'good':'warn'}">${i.reconciled?'Reconciliation recorded. Duplicate records remain inspectable and are excluded from pipeline.':'Legacy inputs include two representations of Northstar. Pipeline is overstated until reconciled.'}</div>`+table(['Source','Opportunity','Canonical key','Unified stage','Disposition'],state.opportunities.map(o=>row([esc(o.sourceId),esc(o.name),esc(o.canonicalKey),esc(M.normalizeStage(o.stage)),o.duplicateOf?tag('Duplicate → '+o.duplicateOf,'warn'):tag('Canonical / unresolved','info')])))+`<div class="grid two">${card('Integration contract','<ul class="check-list"><li>People: named territory owners, backups and capacity</li><li>Process: shared qualification and review cadence</li><li>Systems: retained source IDs and explicit canonical keys</li><li>Customer: one acceptance owner and delivery handoff</li></ul>')}${card('Reconciliation receipt',i.receipt?`<pre>${esc(JSON.stringify(i.receipt,null,2))}</pre>`:'<p>Run reconciliation to create a timestamped change receipt. No source-system write occurs.</p>')}</div>`;}
function people(){const c=M.coverage(state);return head('People, coverage & the second line','Fictional roles make ownership, capacity, coaching and succession concrete.',btn('Assign missing owners & backups','coverage','','primary'))+`<div class="grid two">${c.people.map(p=>card(p.name,`<p>${esc(p.role)}</p><div class="facts"><div><label>Open account load</label><strong>${p.load} / ${p.capacity}</strong></div><div><label>Capacity</label>${tag(p.overloaded?'Over capacity':'Within capacity',p.overloaded?'warn':'good')}</div></div><p>${esc(state.people.find(person=>person.id===p.id)?.coaching||'Coaching objective not yet recorded')}</p><p>Assigned: ${esc(p.assigned.join(', ')||'None')}</p>${btn('Edit role / capacity','edit-person',p.id,'small')} ${btn('Create coaching action','coach',p.id,'small')}`)).join('')}</div>`+card('Coverage exceptions',table(['Account','Owner','Backup','Manage'],M.activeOpportunities(state).map(o=>row([esc(o.name),esc(owner(o.owner)),esc(owner(o.backup)),btn('Assign','edit-opp',o.id,'small')]))));}
function product(){return head('Product scope & partner growth','Convert an outcome into a bounded package, delivery workshare and engineering acceptance contract.')+`<div class="grid two">${D.products.map(p=>card(p.name,`<p>${esc(p.outcome)}</p><p>${esc(p.scope)}</p><ul class="check-list">${p.dependencies.map(d=>`<li>${esc(d)}</li>`).join('')}</ul><div class="callout">${esc(p.proposed)}</div>`)).join('')}</div>`+card('Configure an account package',table(['Pursuit','Package','Partner','Configuration'],M.activeOpportunities(state).map(o=>row([esc(o.name),esc(o.product),esc(state.partners.find(p=>p.id===o.partner)?.name||'Direct'),btn('Configure','edit-opp',o.id,'small')+' '+btn('Solution brief','brief',o.id,'small')]))))+`<div class="grid two">${state.partners.map(p=>card(p.name,`<p>${esc(p.route)} · ${esc(owner(p.owner))}</p><p>Capability ${p.capabilityScore}/5 · access ${p.accessScore}/5 · delivery ${p.deliveryScore}/5</p><p>${esc(p.workshare)}</p>${tag(p.termsKnown?'Terms recorded':'Terms unresolved',p.termsKnown?'good':'warn')}<div class="actions">${btn('Edit partner plan','edit-partner',p.id)}${btn('Create enablement action','partner-action',p.id)}</div>`)).join('')}</div>`+card('Customer requirement → engineering roadmap',table(['Work item','Owner / state','Acceptance criterion','Action'],D.engineeringWork.map(w=>row([`<strong>${esc(w.title)}</strong><small>${esc(w.detail)}</small>`,`${esc(w.owner)}<br>${esc(w.status)}`,esc(w.criterion),btn('Create roadmap task','engineering-action',w.id,'small')]))));}
function replayFigure(){const s=R.run.samples[snapshot],samples=R.run.samples,points=k=>samples.map(p=>`${p[k]*5+30},${(100-p[k+1])*2.4}`).join(' ');return `<svg viewBox="0 0 560 270" role="img" aria-label="Recorded native Fly-0 point-world trajectory, selected tick ${s[0]}"><path d="M30 30V240H530M30 120H530M280 30V240" fill="none" stroke="var(--line)"/><polyline points="${points(1)}" fill="none" stroke="var(--orange)" stroke-width="2"/><polyline points="${points(3)}" fill="none" stroke="var(--blue)" stroke-width="2"/><circle cx="${s[1]*5+30}" cy="${(100-s[2])*2.4}" r="6" fill="var(--orange)"/><circle cx="${s[3]*5+30}" cy="${(100-s[4])*2.4}" r="6" fill="var(--blue)"/><text x="30" y="23" fill="var(--muted)" font-size="11">node-01 / orange · node-02 / blue · extracted recorded snapshots</text><text x="30" y="260" fill="var(--muted)" font-size="11">Tick ${s[0]} · ${s[6]?'HOLD':'moving'} · navigation cue ${s[7]?'present':'absent'}</text></svg>`;}
function room(){const s=R.run.samples[snapshot];return head('Danger Room · original native receipt','Recorded 12 October 2026 Fly-0 baseline execution. Original recorded baseline and capture templates.',btn('Download original receipt','native-download','','primary'))+`<div class="callout info">Native Python execution, synthetic point world. The viewer displays extracted snapshots; it does not execute the native controller or invent missing frames. Hold means zero synthetic velocity, not tested physical stopping.</div><div class="grid two">${card('Recorded trace replay',`<div id="native-plot" class="plot">${replayFigure()}</div><label for="native-scrub">Recorded snapshot <span id="native-label">${snapshot+1} / ${R.run.samples.length} · tick ${s[0]}</span></label><input id="native-scrub" type="range" min="0" max="${R.run.samples.length-1}" value="${snapshot}"><div class="actions">${btn('Play / pause','native-play')}${[40,55,80].map(n=>btn('Tick '+n,'native-jump',String(n),'small')).join('')}</div><div id="native-state" class="callout">${nativeState()}</div>`)}${card('What actually ran',`<div class="facts"><div><label>Controller</label><strong>fly0@1 baseline</strong></div><div><label>World</label><strong>2 agents · 260 ticks · seed 5</strong></div><div><label>Navigation dropout</label><strong>Tick 40–79</strong></div><div><label>First hold during dropout</label><strong>Tick 55</strong></div></div><ul class="check-list">${Object.entries(R.run.checks).map(([k,v])=>`<li>${esc(k)}: ${esc(v)}</li>`).join('')}</ul><p class="fine-print">Receipt reports native ledger/world replay and same-host rerun equality, loopback TCP equality and tamper rejection. These checks are historical recorded results, not a browser rerun.</p><p class="code">Ledger SHA-256<br>${esc(R.run.ledger_sha256)}</p><a href="https://bigbirdreturns.github.io/axm-tools/danger-room/" target="_blank" rel="noopener">Open the unchanged original Danger Room ↗</a>`)}</div>`+card('Camera capture request & templates',`<p>Original proposed interchange templates. They are not camera measurements. The synthetic example CSV explicitly labels every example record.</p><div class="actions">${Object.keys(R.assets).map(n=>btn(n,'asset-download',n,'small')).join('')}</div>`)+card('Analyze a camera log locally',`<p>Upload the original frames CSV format to inspect received frames, declared missing frames, unrepresented sequence gaps and Pi queue latency. Camera and Pi clock domains remain distinct. File bytes stay local and are not retained.</p><div class="field"><label for="camera-file">Frames CSV</label><input type="file" id="camera-file" accept=".csv,text/csv"></div><div class="actions">${btn('Analyze synthetic example','camera-example')}${btn('Export analysis receipt','camera-export')}</div><div id="camera-result">${captureHTML()}</div>`)+card('Boundaries retained',`<ul>${R.run.limits.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>`);}
function captureHTML(){return captureAnalysis?`<div class="callout info">${esc(captureAnalysis.clockBoundary)}</div><div class="facts"><div><label>Received frames</label><strong>${captureAnalysis.receivedFrames}</strong></div><div><label>Explicit missing records</label><strong>${captureAnalysis.explicitMissing}</strong></div><div><label>Unrepresented sequence gaps</label><strong>${captureAnalysis.sequenceGaps}</strong></div><div><label>Late arrivals</label><strong>${captureAnalysis.lateArrivals}</strong></div></div><p>Missing records and unrepresented gaps are reported separately; they are not a claim about where a frame was lost.</p><pre>${esc(JSON.stringify(captureAnalysis,null,2))}</pre>`:'<p class="muted">Choose a CSV or analyze the labelled synthetic example.</p>'; }
function nativeState(){const s=R.run.samples[snapshot];return `Tick ${s[0]} · confidence ${s[5]}/255 · ${s[6]?'HOLD':'not holding'} · navigation cue ${s[7]?'present':'absent'}. ${s[0]>=40&&s[0]<80?'Recorded dropout window.':'Outside recorded dropout window.'}`;}
function updateReplay(){if(view!=='room')return;$('#native-plot').innerHTML=replayFigure();$('#native-label').textContent=`${snapshot+1} / ${R.run.samples.length} · tick ${R.run.samples[snapshot][0]}`;$('#native-scrub').value=snapshot;$('#native-state').textContent=nativeState();}
function school(){const q=state.quality,last=q.runs.at(-1);return head('Danger School · executable reference lab','A new browser reference experiment, separate from native AXM results. Preserve a failure, select an explicit improvement, then run fresh evaluation and retained regressions.',btn('Run baseline failure','baseline')+btn('Run fresh declared suite','suite','','primary'))+`<div class="callout warn">${esc(E.scope)} The supported controller predicts known commanded displacement under ideal actuation. It does not learn unknown dynamics or resolve observation bias.</div><div class="grid two">${card('Declare acceptance before execution',`<label class="field" for="required-scope">Required scope<select id="required-scope"><option value="timing" ${q.requiredScope==='timing'?'selected':''}>Timing: nominal + dropout + delay</option><option value="expanded" ${q.requiredScope==='expanded'?'selected':''}>Expanded: timing + measurement bias</option></select></label><p>Fresh seeds: ${E.freshSeeds.join(', ')}. Development seeds: ${E.developmentSeeds.join(', ')}. Peak ≤ 0.28, RMS ≤ 0.12, final ≤ 0.12 abstract units; no expired measurements.</p><p>Changing the scope revokes any prior acceptance before commercial readiness is calculated.</p>${tag(q.accepted?'Accepted: '+q.accepted.scope:'No current accepted evaluation',q.accepted?'good':'warn')}<div class="actions">${btn('Verify & accept latest suite','accept')}${btn('Retain latest failure as curriculum','curriculum')}</div>`)}${card('Current run evidence',last?`<p>${esc(last.id)}</p>${trajectory(last)}<div class="facts"><div><label>Peak error</label><strong>${num(last.metrics.maxError)}</strong></div><div><label>RMS</label><strong>${num(last.metrics.rmsError)}</strong></div><div><label>Final error</label><strong>${num(last.metrics.finalError)}</strong></div><div><label>Disposition</label>${tag(last.passed?'PASS':'FAIL',last.passed?'good':'bad')}</div></div>${btn('Download complete run','run-download',last.id)}`:'<p>Run the reactive baseline to capture a real failure in this browser. Then evaluate the supported candidate against the entire declared scope.</p>')}</div>`+card('Fresh evaluation suites',table(['Timestamp / cohort','Scope','Result','Integrity / acceptance'],q.suites.map(s=>row([`${esc(s.at)}<small>${esc(s.cohort)}</small>`,esc(s.scope),tag(s.passed+'/'+s.total+' passed',s.allPassed?'good':'bad'),`${esc(s.verified?'All runs verified':'Not verified')} ${q.accepted?.suiteId===s.id?tag('Accepted','good'):''}`]))))+card('Preserved failures & regression curriculum',`<p>Failures stay in the run ledger. Curriculum entries preserve the exact source configuration and are rerun with the supported candidate when a suite executes.</p>`+table(['Case','Source failure','Regression recipe'],q.curriculum.map(c=>row([esc(c.id),esc(c.sourceRunId),esc(JSON.stringify(c.config))]))))+card('Requirement → evidence matrix',table(['Requirement','Method','Evidence'],D.requirements.map(r=>row([esc(r.title),esc(r.method),esc(r.kind==='timing'?(q.accepted?.scope==='timing'?'Accepted timing suite':'Current scope / suite required'):r.kind==='expanded'?'Bias test is retained as an expected limitation':r.kind==='evidence'?q.runs.length+' preserved browser runs':'Owner review required')]))));}
function trajectory(r){const points=r.frames.map(f=>`${(f.x+1.8)*100},${(1.3-f.y)*80}`).join(' '),target=r.frames.map(f=>`${(f.targetX+1.8)*100},${(1.3-f.targetY)*80}`).join(' ');return `<svg class="plot" viewBox="0 0 360 210" role="img" aria-label="Browser reference target and tracked trajectory"><polyline points="${target}" stroke="var(--muted)" stroke-dasharray="4 4" fill="none"/><polyline points="${points}" stroke="var(--orange)" stroke-width="2" fill="none"/><text x="12" y="197" fill="var(--muted)" font-size="9">Dashed: target · orange: candidate · abstract units</text></svg>`;}
function review(){const m=M.metrics(state);return head('Operating review','A current, auditable snapshot. Illustrative stage weighting is not calibrated probability; no forecast accuracy or growth history is invented.',btn('Export MBR / QBR HTML','review-html')+btn('Export review JSON','review-json','','primary'))+metrics()+`<div class="toolbar"><label for="as-of">Review as of</label><input id="as-of" type="date" value="${esc(state.asOf)}">${btn('Generate current gap actions','gaps')}</div>`+(state.integration.beforeAfter?card('Working day · before and after',table(['Measure','Before','After'],Object.entries(state.integration.beforeAfter.before).map(([k,v])=>row([esc(k),esc(v),esc(state.integration.beforeAfter.after[k])])))):'')+table(['Account','Forecast','Value / weighted','Blockers'],m.forecast.map(f=>row([esc(state.opportunities.find(o=>o.id===f.id).name),tag(f.category,f.category==='commit'?'good':f.category==='excluded'?'bad':'warn'),money(f.amount)+'<br>'+money(f.weightedAmount),esc(f.blockers.join('; ')||'All commit gates recorded')])))+`<div class="grid two">${card('Accountable action register',actionsList())}${card('Review policy',`<ul>${m.caveats.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>Suggested cadence: weekly pursuit and capacity check; monthly forecast, partner and evidence review; quarterly market, product and succession decisions.</p><p>Meridian can be technically ready while customer acceptance remains unresolved. Record customer acceptance only as an explicit operator assertion in its form.</p>`)}</div>`;}
function evidence(){return '<div class="callout"><a href="standalone.html" download>Download the complete offline workbench ↗</a> · Save the workspace JSON separately to carry your current records.</div>'+head('Evidence & customer handoff','Sources, dated estate evidence and generated handoff records retain their original scope.',btn('Generate delivery handoff','handoff','','primary'))+`<div class="grid two">${D.evidence.map(e=>card(e.title,`${tag(e.tier,'info')}<p class="fine-print">${esc(e.date)} · ${esc(e.id)}</p><p>${esc(e.claim)}</p><div class="callout warn">${esc(e.limit)}</div>${e.receiptSha256?`<p class="code">${esc(e.receiptSha256)}</p>`:''}`)).join('')}</div>`+card('Source register',`<ul class="source-list">${D.sources.map(s=>`<li><a href="${safeURL(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><p>${esc(s.claim)}<small>Retrieved ${esc(s.retrieved)}</small></p></li>`).join('')}</ul>`)+card('Agent-authored function map',`<p>These are explicit workbench roles and active navigation paths, not autonomous live model sessions. Buttons open the corresponding working function.</p><div class="cards">${D.functions.map(f=>`<article class="agent-card"><span class="eyebrow">${esc(f.agent)}</span><h3>${esc(f.title)}</h3><p>${esc(f.scope)}</p><p>${esc(f.output)}</p>${btn('Inspect function','navigate',f.view,'small')}</article>`).join('')}</div>`)+card('Event receipts',table(['Time','Action','Recorded detail'],state.events.slice(-40).reverse().map(e=>row([esc(e.at),esc(e.action),esc(JSON.stringify(e.detail))]))));}
function safeURL(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
const renderers={today,accounts,integration,people,product,room,school,review,evidence};
function render(){if(playing&&view!=='room'){clearInterval(playing);playing=null;}$('#nav').innerHTML=views.map(([id,title],i)=>`<button type="button" data-action="navigate" data-id="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${title}</button>`).join('');$('#view').innerHTML=(storageError?`<div class="callout bad" role="alert">${esc(storageError)}</div>`:'')+renderers[view]();status();}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal();}
const field=(label,name,value='',type='text')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''}></div>`;
const select=(label,name,value,options)=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const area=(label,name,value='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
const check=(label,name,value)=>`<label class="field" for="f-${name}"><span><input id="f-${name}" type="checkbox" name="${name}" ${value?'checked':''}> ${esc(label)}</span></label>`;
function formWrap(kind,id,body){return `<form data-form="${kind}" data-id="${esc(id)}"><div class="form-grid">${body}</div><div class="callout bad form-error" role="alert" hidden></div><div class="actions"><button type="submit" class="btn primary">Save local record</button></div></form>`;}
function editOpp(id){const o=state.opportunities.find(o=>o.id===id)||{id:'OP-'+Date.now(),name:'',amount:0,stage:'Lead',region:'EMEA',technical:'external'};modal(id?'Edit pursuit · '+o.name:'New fictional pursuit',formWrap('opp',o.id,field('Account name','name',o.name)+field('Amount · fictional USD','amount',o.amount,'number')+field('Region','region',o.region)+field('Segment','segment',o.segment)+select('Stage','stage',M.normalizeStage(o.stage),Object.keys(M.weights).map(s=>[s,s]))+field('Close date','closeDate',o.closeDate,'date')+select('Accountable owner','owner',o.owner||'',[['','Unassigned'],...state.people.map(p=>[p.id,p.name])])+select('Backup owner','backup',o.backup||'',[['','Unassigned'],...state.people.map(p=>[p.id,p.name])])+select('Product package','product',o.product||'quality',D.products.map(p=>[p.id,p.name]))+select('Delivery partner','partner',o.partner||'',[['','Direct'],...state.partners.map(p=>[p.id,p.name])])+select('Technical evidence lane','technical',o.technical,[['external','External operator assertion'],['browser','Browser reference evaluation']])+select('External evidence assertion','externalEvidence',o.externalEvidence||'pending',[['pending','Pending / unverified'],['verified','Operator asserts verified']])+field('Source record ID','sourceId',o.sourceId)+field('Canonical opportunity key','canonicalKey',o.canonicalKey)+check('Buyer authority recorded (operator assertion)','buyer',o.buyer)+check('Budget recorded (operator assertion)','budget',o.budget)+check('Procurement recorded (operator assertion)','procurement',o.procurement)+check('Customer acceptance recorded (explicit sample assertion)','customerAcceptance',o.customerAcceptance)+area('Customer need / outcome','need',o.need)+area('Next decision / action','next',o.next)+area('Value hypothesis','valueHypothesis',o.valueHypothesis)));}
function brief(id){const b=M.commercialBrief(state,id),o=state.opportunities.find(o=>o.id===id),p=D.products.find(p=>p.id===o.product);modal('Pursuit / solution brief',`<span class="eyebrow">Fictional commercial record · ${esc(b.asOf)}</span><h3>${esc(b.name)}</h3><p>${esc(o.need)}</p><div class="facts"><div><label>Commercial owner</label><strong>${esc(owner(b.owner))}</strong></div><div><label>Forecast</label>${tag(b.forecast.category)}</div><div><label>Package</label><strong>${esc(p?.name||b.product)}</strong></div><div><label>Close / amount</label><strong>${esc(b.closeDate)} · ${money(b.amount)}</strong></div></div><h3>Value & acceptance</h3><p>${esc(o.valueHypothesis)}</p><p>${esc(p?.scope||'Package not configured')}</p><div class="callout ${b.technical.passed?'good':'warn'}">${esc(b.technical.label)}. ${esc(b.technical.provenance)}</div><h3>Next decisions</h3><ul>${b.blockers.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Commit gates recorded; operator review still owns the decision.</li>'}</ul><p>${esc(o.next)}</p>${btn('Download brief JSON','brief-download',id)}`);}
function addAction(title,ownerId='SOLUTIONS',oppId=null,kind='gap'){const existing=state.actions.find(a=>a.title===title&&a.oppId===oppId&&a.status!=='done');if(existing)return;state.actions.push({id:'ACT-'+Date.now()+'-'+state.actions.length,title,owner:ownerId,oppId,kind,due:new Date(Date.parse(state.asOf+'T00:00:00Z')+7*86400000).toISOString().slice(0,10),status:'open',createdAt:stamp()});}
function gaps(){for(const o of M.activeOpportunities(state)){const f=M.forecastOne(o,state);if(!f.open)continue;for(const gap of f.blockers)addAction(gap,o.owner||'APAC',o.id);if(!o.backup||o.backup===o.owner)addAction('Assign an independent backup owner',o.owner||'APAC',o.id);}for(const p of state.partners)if(!p.termsKnown)addAction('Agree terms and workshare: '+p.name,p.owner,null,'partner');}
function coverage(){for(const o of M.activeOpportunities(state)){if(!o.owner)o.owner=o.region==='APAC'?'APAC':'EMEA';if(!o.backup||o.backup===o.owner)o.backup=o.owner==='SOLUTIONS'?'PARTNER':'SOLUTIONS';}}
async function sealRun(r){try{await E.seal(r);}catch(e){r.sealError=e.message;}state.quality.runs.push(r);return r;}
async function baseline(){const r=await sealRun(E.run({seed:42,controller:'reactive',fault:'dropout'}));event('Baseline run preserved',{runId:r.id,passed:r.passed});return r;}
async function suite(){const q=state.quality,faults=q.requiredScope==='timing'?['none','dropout','delay']:['none','dropout','delay','bias'];q.accepted=null;const s=E.runSuite({seeds:E.freshSeeds,faults,controller:'supported'});for(const r of s.runs)await sealRun(r);const regressions=[];for(const c of q.curriculum){const r=await sealRun(E.run({...c.config,controller:'supported'}));regressions.push(r);}const all=[...s.runs,...regressions],verified=(await Promise.all(all.map(r=>E.verify(r)))).every(Boolean);const receipt={id:'SUITE-'+Date.now(),at:stamp(),scope:q.requiredScope,runIds:s.runs.map(r=>r.id),regressionRunIds:regressions.map(r=>r.id),curriculumIds:q.curriculum.map(c=>c.id),seeds:[...s.seeds],faults:[...s.faults],cohort:s.cohort,total:all.length,passed:all.filter(r=>r.passed).length,allPassed:all.every(r=>r.passed),verified};q.suites.push(receipt);event('Fresh evaluation suite executed',{suiteId:receipt.id,scope:receipt.scope,passed:receipt.passed,total:receipt.total,verified});return receipt;}
async function verifyRunRecord(r,requireSeal=false){
 if(!r||!r.config)throw Error('Run evidence is missing its configuration.');
 const payload=Object.fromEntries(Object.entries(r).filter(([k])=>!['integrity','sealError'].includes(k)));
 if(E.canonical(E.run(r.config))!==E.canonical(payload))throw Error('Run '+r.id+' differs from deterministic replay; imported metrics or checks cannot establish acceptance.');
 if((requireSeal||r.integrity)&&!(await E.verify(r)))throw Error('Run '+r.id+' has missing or invalid integrity evidence.');
 return true;
}
async function validateAcceptedState(candidate){
 validate(candidate);const q=candidate.quality,a=q.accepted;
 // Even an unaccepted imported trajectory must match the executable model.
 for(const r of q.runs)await verifyRunRecord(r,false);
 if(!a)return null;
 const s=q.suites.find(s=>s.id===a.suiteId),required=q.requiredScope==='timing'?['none','dropout','delay']:['none','dropout','delay','bias'];
 if(!s||a.scope!==q.requiredScope||s.scope!==q.requiredScope)throw Error('Accepted evidence does not match the required scope and referenced suite.');
 if(!s.allPassed)throw Error('Acceptance blocked: the declared suite contains failed cases.');
 if(!s.verified){const failed=q.runs.find(r=>r.sealError);throw Error('Acceptance blocked: suite integrity could not be verified.'+(failed?' '+failed.sealError:''));}
 if(!a.allPassed||!a.verified)throw Error('Acceptance record does not assert complete passing, verified evidence.');
 if(!Array.isArray(s.runIds)||!Array.isArray(s.regressionRunIds)||!Array.isArray(a.runIds))throw Error('Suite run references are missing.');
 const find=id=>q.runs.findLast(r=>r.id===id),runs=s.runIds.map(find),reg=s.regressionRunIds.map(find);
 if(runs.length!==E.freshSeeds.length*required.length||new Set(s.runIds).size!==s.runIds.length||E.freshSeeds.some(seed=>required.some(fault=>!runs.some(r=>r&&r.config.seed===seed&&r.config.fault===fault&&r.config.controller==='supported'&&r.config.ticks===240&&r.config.dt===.05))))throw Error('Accepted suite must contain the complete fixed fresh-seed and fault Cartesian evaluation.');
 if(E.canonical(s.seeds)!==E.canonical([...E.freshSeeds])||E.canonical(s.faults)!==E.canonical(required))throw Error('Suite declaration differs from the required fixed evaluation.');
 const curriculum=q.curriculum.filter(c=>!c.at||!s.at||c.at<=s.at);
 if(s.curriculumIds&&(s.curriculumIds.length!==curriculum.length||curriculum.some(c=>!s.curriculumIds.includes(c.id))))throw Error('Suite curriculum declaration is incomplete.');
 if(reg.length!==curriculum.length)throw Error('Retained curriculum regressions are incomplete.');
 for(const c of curriculum){const source=find(c.sourceRunId);if(!source||source.passed||E.canonical(source.config)!==E.canonical(c.config))throw Error('Curriculum source is not the referenced retained failure.');await verifyRunRecord(source,true);const expected=E.canonical({...c.config,controller:'supported'});if(!reg.some(r=>r&&E.canonical(r.config)===expected))throw Error('Suite omitted a required retained regression.');}
 const all=[...runs,...reg];if(!all.every(r=>r&&r.passed&&r.checks.every(c=>c.passed)))throw Error('Acceptance blocked: every declared fresh case and retained regression must pass.');
 if(s.total!==all.length||s.passed!==all.length)throw Error('Suite totals do not match the complete passing evidence.');
 if(a.runIds.length!==all.length||a.runIds.some((id,i)=>id!==all[i].id))throw Error('Accepted run references differ from the referenced suite.');
 for(const r of all)await verifyRunRecord(r,true);
 return clone(a);
}
async function accept(){const q=state.quality,s=q.suites.at(-1);if(!s||s.scope!==q.requiredScope)throw Error('Run a fresh suite for the current declared scope first.');const admission={suiteId:s.id,scope:s.scope,runIds:[...s.runIds,...s.regressionRunIds],allPassed:true,verified:true,at:stamp(),meaning:E.scope},candidate=clone(state);candidate.quality.accepted=admission;await validateAcceptedState(candidate);q.accepted=admission;event('Scoped browser acceptance recorded',{suiteId:s.id,scope:s.scope});}

function measures(){const m=M.metrics(state),c=M.coverage(state);return {'Open pipeline':money(m.openPipeline),'Commit':money(m.commit),'Coverage':Math.round(c.coveragePct)+'%','Backup gaps':c.backupGaps.length,'Accepted scope':state.quality.accepted?.scope||'None'};}
async function workingDay(){const before=measures();state.integration.receipt={at:stamp(),...M.reconcile(state)};coverage();const r=await baseline();if(!r.passed&&!state.quality.curriculum.some(c=>c.sourceRunId===r.id))state.quality.curriculum.push({id:'CASE-'+Date.now(),sourceRunId:r.id,config:clone(r.config),at:stamp()});state.quality.requiredScope='timing';state.quality.accepted=null;await suite();await accept();gaps();state.integration.beforeAfter={at:stamp(),before,after:measures()};event('Working day completed',{customerAcceptance:'Not changed; explicit operator action still required'});view='review';}
function reviewDocument(){const r=M.operatingReview(state);return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Simulation Director operating review</title><body><h1>Simulation Director · MBR / QBR</h1><p>As of ${esc(state.asOf)} · generated ${esc(stamp())}</p><p>${esc(r.provenance)}</p><h2>Current forecast</h2><ul><li>Open pipeline: ${money(r.metrics.openPipeline)}</li><li>Illustrative weighted pipeline: ${money(r.metrics.weightedPipeline)}</li><li>Commit: ${money(r.metrics.commit)}</li><li>Closed-won bookings: ${money(r.metrics.bookings)}</li><li>Recognized revenue: not supplied</li></ul><h2>Pursuits and decision gaps</h2>${r.pursuits.map(p=>`<h3>${esc(p.name)} · ${esc(p.forecast.category)}</h3><p>${money(p.amount)} · ${esc(owner(p.owner))} · ${esc(p.closeDate)}</p><ul>${p.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`).join('')}<h2>Quality boundary</h2><p>${esc(E.scope)}</p><pre>${esc(JSON.stringify(r.quality,null,2))}</pre><h2>Actions</h2><ul>${r.actions.map(a=>`<li>${esc(a.title)} · ${esc(owner(a.owner))} · ${esc(a.status)}</li>`).join('')}</ul><h2>Review caveats</h2><ul>${r.caveats.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></body></html>`;}
async function dispatch(action,id){if(action==='navigate'){view=renderers[id]?id:'today';render();return;}if(busy){toast('An evaluation is running. Please wait.');return;}try{busy=true;switch(action){case'working-day':await workingDay();break;case'reconcile':state.integration.receipt={at:stamp(),...M.reconcile(state)};event('Legacy source reconciliation',state.integration.receipt);break;case'coverage':coverage();event('Owner and backup coverage assigned');break;case'gaps':gaps();event('Current decision gaps converted to actions');break;case'edit-opp':editOpp(id);return;case'new-opp':editOpp();return;case'brief':brief(id);return;case'brief-download':download(id+'-brief.json',M.commercialBrief(state,id));return;case'action-toggle':{const a=state.actions.find(a=>a.id===id);a.status=a.status==='done'?'open':'done';event('Action disposition changed',{id,status:a.status});break;}case'coach':{const p=state.people.find(p=>p.id===id);addAction('Coaching: '+p.coaching,id,null,'coaching');event('Coaching action created',{person:id});break;}case'edit-person':{const p=state.people.find(p=>p.id===id);modal('Edit role / capacity',formWrap('person',id,field('Role name','name',p.name)+field('Role remit','role',p.role)+field('Open account capacity','capacity',p.capacity,'number')+area('Coaching objective','coaching',p.coaching)));return;}case'edit-partner':{const p=state.partners.find(p=>p.id===id);modal('Partner plan',formWrap('partner',id,field('Partner name','name',p.name)+field('Route to market','route',p.route)+select('Partner owner','owner',p.owner,state.people.map(p=>[p.id,p.name]))+field('Capability score · 0–5','capabilityScore',p.capabilityScore,'number')+field('Access score · 0–5','accessScore',p.accessScore,'number')+field('Delivery score · 0–5','deliveryScore',p.deliveryScore,'number')+check('Terms recorded (operator assertion)','termsKnown',p.termsKnown)+area('Delivery workshare and attribution','workshare',p.workshare)));return;}case'partner-action':{const p=state.partners.find(p=>p.id===id);addAction('Enable '+p.name+': agree terms, attribution and delivery acceptance',p.owner,null,'partner');event('Partner enablement action created',{partner:id});break;}case'engineering-action':{const w=D.engineeringWork.find(w=>w.id===id);addAction(w.title+': '+w.criterion,'SOLUTIONS',null,'engineering');event('Engineering roadmap task created',{work:id});break;}case'camera-example':captureAnalysis=globalThis.SDcapture.inspectFrames(R.assets['frames.SYNTHETIC_EXAMPLE.csv']);event('Synthetic camera example analyzed');break;case'camera-export':if(!captureAnalysis)throw Error('Analyze a camera log first.');download('camera-analysis.json',{at:stamp(),analysis:captureAnalysis});return;case'native-download':download('danger-room-native-2026-10-12.json',R.run);return;case'asset-download':download(id,R.assets[id],id.endsWith('.csv')?'text/csv':'application/json');return;case'native-jump':snapshot=R.run.samples.findIndex(s=>s[0]===Number(id));updateReplay();return;case'native-play':if(playing){clearInterval(playing);playing=null;}else{playing=setInterval(()=>{snapshot=(snapshot+1)%R.run.samples.length;updateReplay();},380);}return;case'baseline':await baseline();break;case'suite':await suite();break;case'accept':await accept();break;case'curriculum':{const r=state.quality.runs.findLast(r=>!r.passed);if(!r)throw Error('Run and preserve a failing baseline first.');if(!state.quality.curriculum.some(c=>c.sourceRunId===r.id))state.quality.curriculum.push({id:'CASE-'+Date.now(),sourceRunId:r.id,config:clone(r.config),at:stamp()});state.quality.accepted=null;event('Failure retained in regression curriculum',{runId:r.id});break;}case'run-download':download(id+'.json',state.quality.runs.findLast(r=>r.id===id));return;case'review-json':event('Operating review exported',{format:'JSON'});download('simulation-operating-review.json',M.operatingReview(state));return;case'review-html':event('Operating review exported',{format:'HTML'});download('simulation-operating-review.html',reviewDocument(),'text/html');return;case'market-brief':modal('Market / demand brief',`<h3>A measurable discovery campaign</h3><p>Target: primes, integrators and research teams with a repeatable simulation evaluation problem. Offer: one interface discovery workshop and one written acceptance contract.</p><p>Channel: partner-led introductions and practitioner evaluation sessions. Owner: ${esc(owner('PARTNER'))}. Hypothesis: useful evidence converts discovery into a qualified pursuit. Measure responses, discovery meetings and qualified opportunities against a dated cohort.</p><h3>Current account priorities</h3><ol>${M.rankAccounts(state).map(r=>`<li>${esc(r.name)} · ${r.score}/100 · ${esc(r.opportunity.next)}</li>`).join('')}</ol><p>No outreach is sent by this application.</p>`);event('Market brief generated');return;case'handoff':{const handoff={at:stamp(),scope:state.quality.requiredScope,accepted:state.quality.accepted,installationOwner:owner('SOLUTIONS'),customerSuccessOwner:owner('EMEA'),incidentOwner:owner('SOLUTIONS'),successorOwner:owner('PARTNER'),requirements:D.requirements,engineeringOpen:D.engineeringWork,partnerWorkshare:state.partners,opportunities:M.activeOpportunities(state).map(o=>M.commercialBrief(state,o.id)),limits:[E.scope,'Real deployment requires actual interfaces, customer evidence, rights and named customer owners.'],provenance:M.provenance};event('Delivery handoff generated');download('simulation-delivery-handoff.json',handoff);modal('Handoff package generated',`<p>The downloaded package joins current pursuit decisions, accepted scope, requirement traceability, delivery workshare and open engineering limits.</p><div class="facts"><div><label>Installation / incident</label><strong>${esc(owner('SOLUTIONS'))}</strong></div><div><label>Customer success</label><strong>${esc(owner('EMEA'))}</strong></div><div><label>Successor</label><strong>${esc(owner('PARTNER'))}</strong></div><div><label>Accepted browser scope</label><strong>${esc(state.quality.accepted?.scope||'None; release blocked')}</strong></div></div><div class="callout warn">Fictional role assignments. Customer deployment and customer acceptance remain separate real-world decisions.</div>`);return;}case'intake':modal('Local source intake',`<p>Paste a JSON array of opportunity records or an object with an opportunities array. IDs must be unique; existing IDs update their records. This is a local import, with no connection to a CRM.</p>${formWrap('intake','',area('Opportunity JSON','json','[]'))}`);return;}save();render();toast('Workspace updated.');}catch(e){save();render();toast(e.message);modal('Decision blocked / action needs attention',`<div class="callout bad" role="alert">${esc(e.message)}</div><p>Your prior runs and source records remain preserved. Review the declared scope and evidence before trying again.</p>`);}finally{busy=false;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)dispatch(b.dataset.action,b.dataset.id);});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();try{const fd=new FormData(f),values=Object.fromEntries(fd),kind=f.dataset.form,id=f.dataset.id;if(kind==='opp'){if(!values.name.trim())throw Error('Account name is required.');values.amount=Number(values.amount);if(!Number.isFinite(values.amount)||values.amount<0)throw Error('Use a nonnegative finite amount.');for(const k of ['buyer','budget','procurement','customerAcceptance'])values[k]=fd.has(k);for(const k of ['owner','backup','partner'])values[k]=values[k]||null;if(values.owner&&values.owner===values.backup)throw Error('Backup must be different from accountable owner.');let o=state.opportunities.find(o=>o.id===id);if(o)Object.assign(o,values);else state.opportunities.push({id,...values,duplicateOf:null});}else if(kind==='person'){values.capacity=Number(values.capacity);if(!Number.isInteger(values.capacity)||values.capacity<0)throw Error('Capacity must be a nonnegative whole number.');Object.assign(state.people.find(p=>p.id===id),values);}else if(kind==='partner'){for(const k of ['capabilityScore','accessScore','deliveryScore']){values[k]=Number(values[k]);if(!Number.isFinite(values[k])||values[k]<0||values[k]>5)throw Error('Partner scores must be between 0 and 5.');}values.termsKnown=fd.has('termsKnown');Object.assign(state.partners.find(p=>p.id===id),values);}else if(kind==='intake'){if(values.json.length>2000000)throw Error('Source intake is limited to 2 MB.');const input=JSON.parse(values.json),records=Array.isArray(input)?input:input.opportunities;if(!Array.isArray(records)||!records.length)throw Error('Provide at least one opportunity record.');const next=clone(state);for(const r of records){if(!r||typeof r.id!=='string'||typeof r.name!=='string')throw Error('Each record needs a string id and name.');if(['__proto__','constructor','prototype'].some(k=>Object.hasOwn(r,k)))throw Error('Unsafe record key.');const i=next.opportunities.findIndex(o=>o.id===r.id);if(i>=0)next.opportunities[i]={...next.opportunities[i],...r};else next.opportunities.push({...r});}validate(next);state=next;state.quality.accepted=null;}event('Local record saved',{kind,id});$('#dialog').close();render();toast('Local record saved; forecast recalculated.');}catch(err){const error=f.querySelector('.form-error');error.hidden=false;error.textContent=err.message;}});
document.addEventListener('input',e=>{if(e.target.id==='native-scrub'){snapshot=Number(e.target.value);updateReplay();}});
document.addEventListener('change',async e=>{if(e.target.id==='camera-file'){try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('Camera CSV exceeds 5 MiB.');const text=await f.text();captureAnalysis=globalThis.SDcapture.inspectFrames(text);let sha256=null;if(globalThis.crypto?.subtle){const hash=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());sha256=Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('');}captureAnalysis.source={name:f.name,size:f.size,sha256,at:stamp(),bytesRetained:false};event('Local camera log inspected',captureAnalysis.source);$('#camera-result').innerHTML=captureHTML();}catch(err){toast(err.message);}}if(e.target.id==='required-scope'){state.quality.requiredScope=e.target.value;state.quality.accepted=null;event('Required acceptance scope changed; prior acceptance revoked',{scope:e.target.value});render();}if(e.target.id==='as-of'){if(!e.target.value)return;state.asOf=e.target.value;event('Review as-of date changed',{asOf:state.asOf});render();}});
$('#dialog-close').addEventListener('click',()=>$('#dialog').close());$('#theme-toggle').addEventListener('click',()=>{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('#theme-toggle').textContent=light?'Dark theme':'Light theme';});
$('#export-workspace').addEventListener('click',()=>{event('Full workspace exported');download('simulation-director-workspace.json',state);});$('#import-workspace').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('Workspace exceeds the 30 MB import limit.');const next=validate(JSON.parse(await file.text()));await validateAcceptedState(next);state=next;storageError='';event('Workspace imported',{filename:file.name,note:'Evidence replay and accepted suite verified before admission'});render();toast('Workspace loaded; valid accepted evidence preserved after verification.');}catch(err){modal('Workspace import failed',`<div class="callout bad" role="alert">${esc(err.message)}</div><p>The active workspace was not replaced.</p>`);}e.target.value='';});
globalThis.SDApp={getState:()=>state,render,dispatch,validate,accept,suite,workingDay,validateAcceptedState,validateQuality:()=>validateAcceptedState(clone(state))};
render();
if(bootCandidate.quality.accepted){validateAcceptedState(bootCandidate).then(accepted=>{state.quality.accepted=accepted;storageError='';save();render();}).catch(err=>{storageError='Saved acceptance was not restored: '+err.message;render();}).finally(()=>{busy=false;});}
})();
